const stockTags={
  '新易盛':['算力','光模块','CPO','高成长'],
  '中际旭创':['算力','光模块','CPO','高成长'],
  '天孚通信':['光模块','CPO','观察'],
  '寒武纪':['算力','半导体','高波动'],
  '汇川技术':['工业自动化','机器人','长期'],
  '招商银行':['银行','高股息','底仓'],
  '腾讯控股':['港股','互联网','长期'],
  '苹果':['美股','消费电子','长期'],
  '贵州茅台':['消费','白酒','高股息'],
  '宁德时代':['新能源','电池','高成长'],
  '立讯精密':['消费电子','苹果链','观察'],
  '长江电力':['公用事业','高股息','底仓'],
  '中国神华':['煤炭','高股息','周期'],
  '比亚迪':['新能源','汽车','观察']
};
let activeStockTagFilters=new Set(),tagMatchMode='any';
const tagFilterButton=document.createElement('button');tagFilterButton.className='vertical-tag-filter-button';tagFilterButton.id='vertical-tag-filter';tagFilterButton.innerHTML='<i data-icon="filter"></i><span>标签</span><b hidden>0</b>';$('#vertical-sort').before(tagFilterButton);hydrateIcons(tagFilterButton);
const activeTagIndicator=document.createElement('div');activeTagIndicator.className='vertical-active-tags';activeTagIndicator.style.display='none';$('.vertical-list-tools').after(activeTagIndicator);
const tagEditorButton=document.createElement('button');tagEditorButton.className='button compact ghost stock-tag-editor-button';tagEditorButton.innerHTML='<i data-icon="edit"></i>标签';$('#vertical-watch-toggle').before(tagEditorButton);hydrateIcons(tagEditorButton);
const baseVerticalItemsForGroup=verticalItemsForGroup;
verticalItemsForGroup=function(){const items=baseVerticalItemsForGroup();if(!activeStockTagFilters.size)return items;return items.filter(item=>{const tags=stockTags[item.name]||[];return tagMatchMode==='all'?[...activeStockTagFilters].every(tag=>tags.includes(tag)):[...activeStockTagFilters].some(tag=>tags.includes(tag))})};
function renderActiveStockTagFilters(){const button=$('#vertical-tag-filter'),count=activeStockTagFilters.size;button.classList.toggle('active',count>0);const badge=$('b',button);badge.hidden=!count;badge.textContent=count;const indicator=$('.vertical-active-tags');indicator.style.display=count?'flex':'none';if(!count){indicator.innerHTML='';return}indicator.innerHTML=`<span class="active-tag-label">${tagMatchMode==='all'?'同时包含':'任一标签'}</span>${[...activeStockTagFilters].map(tag=>`<button class="stock-tag" data-remove-filter-tag="${tag}" title="点击移除">${tag} ×</button>`).join('')}<button class="clear-tag-filter" id="clear-stock-tag-filter">清空</button>`;$$('[data-remove-filter-tag]',indicator).forEach(btn=>btn.addEventListener('click',()=>{activeStockTagFilters.delete(btn.dataset.removeFilterTag);renderVerticalList();updateVerticalSummary()}));$('#clear-stock-tag-filter').addEventListener('click',()=>{activeStockTagFilters.clear();renderVerticalList();updateVerticalSummary()})}
const baseTaggedVerticalList=renderVerticalList;
renderVerticalList=function(){baseTaggedVerticalList();$$('.vertical-stock-row').forEach(row=>{const tags=stockTags[row.dataset.stock]||[],third=$('.vertical-stock-third',row);if(!third)return;const tagContainer=document.createElement('span');tagContainer.className='vertical-stock-tags';tagContainer.title=tags.length?`标签：${tags.join('、')}`:'尚未添加标签';tagContainer.innerHTML=tags.length?`${tags.slice(0,2).map(tag=>`<span class="stock-tag">${tag}</span>`).join('')}${tags.length>2?`<span class="stock-tag more">+${tags.length-2}</span>`:''}`:'<span class="stock-tag more">无标签</span>';third.insertBefore(tagContainer,$('.v-conclusion',third))});renderActiveStockTagFilters()};
const baseTagSelectStock=selectStock;selectStock=function(name){baseTagSelectStock(name);const tags=stockTags[name]||[];$('#summary-tags').innerHTML=tags.map(tag=>`<span>#${tag}</span>`).join('')||'<span>暂无标签</span>'};
function openStockTagEditor(){const name=activeStock;let editing=[...(stockTags[name]||[])];const modal=enhancedDialog('stock-tags-dialog',`${name} · 股票标签`,'<p class="dialog-subtitle">标签用于自选清单筛选。一只股票可以拥有多个标签，标签之间互不影响。</p><div class="tag-editor-current" id="tag-editor-current"></div><div class="tag-add-row"><input id="new-stock-tag" placeholder="输入新标签，按 Enter 添加" maxlength="12"/><button class="button ghost" id="add-stock-tag">添加</button></div><div class="tag-suggestions" id="tag-suggestions"><span>常用标签</span></div>',{actions:'<button class="button ghost" id="cancel-stock-tags">取消</button><button class="button primary" id="save-stock-tags">保存标签</button>'});const suggestions=['算力','光模块','CPO','高股息','长期','观察','高成长','底仓','新能源','半导体','港股','美股'];$('#tag-suggestions',modal).innerHTML+=suggestions.map(tag=>`<button data-suggest-tag="${tag}">+ ${tag}</button>`).join('');function renderEditing(){const container=$('#tag-editor-current',modal);container.innerHTML=editing.length?editing.map(tag=>`<span class="stock-tag">${tag}<button data-remove-editing-tag="${tag}" title="移除">×</button></span>`).join(''):'<span class="muted-text" style="font-size:10px">暂无标签，可在下方添加</span>';$$('[data-remove-editing-tag]',container).forEach(btn=>btn.addEventListener('click',()=>{editing=editing.filter(tag=>tag!==btn.dataset.removeEditingTag);renderEditing()}))}function addTag(tag){tag=tag.trim().replace(/^#/,'');if(!tag||editing.includes(tag))return;editing.push(tag);$('#new-stock-tag',modal).value='';renderEditing()}$('#add-stock-tag',modal).addEventListener('click',()=>addTag($('#new-stock-tag',modal).value));$('#new-stock-tag',modal).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addTag(e.target.value)}});$$('[data-suggest-tag]',modal).forEach(btn=>btn.addEventListener('click',()=>addTag(btn.dataset.suggestTag)));$('#cancel-stock-tags',modal).addEventListener('click',()=>closeEnhancedDialog('stock-tags-dialog'));$('#save-stock-tags',modal).addEventListener('click',()=>{stockTags[name]=[...editing];extraStockDetails[name].tags=editing.map(tag=>`#${tag}`);renderVerticalList();selectStock(name);closeEnhancedDialog('stock-tags-dialog');toast(`${name}的 ${editing.length} 个标签已保存`)});renderEditing()}
tagEditorButton.addEventListener('click',openStockTagEditor);
tagFilterButton.addEventListener('click',()=>{const tags=[...new Set(Object.values(stockTags).flat())].sort((a,b)=>a.localeCompare(b,'zh-CN'));const modal=enhancedDialog('stock-tag-filter-dialog','按标签筛选股票','<div class="tag-match-mode"><span>多标签组合方式</span><div class="segmented small"><button data-tag-match="any" class="active">任一匹配</button><button data-tag-match="all">全部匹配</button></div></div><div class="tag-filter-list">'+tags.map(tag=>`<label class="tag-filter-option"><span><span class="stock-tag">${tag}</span><small>${Object.values(stockTags).filter(list=>list.includes(tag)).length} 只</small></span><input type="checkbox" data-filter-tag-option="${tag}" ${activeStockTagFilters.has(tag)?'checked':''}/></label>`).join('')+'</div>',{subtitle:'任一匹配：包含任意一个所选标签即可。全部匹配：必须同时包含所有所选标签。',actions:'<button class="button ghost" id="reset-tag-filter-options">清空选择</button><button class="button primary" id="apply-tag-filter">应用筛选</button>'});let mode=tagMatchMode;$$('[data-tag-match]',modal).forEach(btn=>{btn.classList.toggle('active',btn.dataset.tagMatch===mode);btn.addEventListener('click',()=>{mode=btn.dataset.tagMatch;$$('[data-tag-match]',modal).forEach(el=>el.classList.toggle('active',el===btn))})});$('#reset-tag-filter-options',modal).addEventListener('click',()=>{$$('[data-filter-tag-option]',modal).forEach(input=>input.checked=false)});$('#apply-tag-filter',modal).addEventListener('click',()=>{activeStockTagFilters=new Set($$('[data-filter-tag-option]:checked',modal).map(input=>input.dataset.filterTagOption));tagMatchMode=mode;renderVerticalList();updateVerticalSummary();const first=$('.vertical-stock-row:not([hidden])');if(first&&!$(`.vertical-stock-row[data-stock="${activeStock}"]`))selectStock(first.dataset.stock);closeEnhancedDialog('stock-tag-filter-dialog');toast(activeStockTagFilters.size?`已按 ${activeStockTagFilters.size} 个标签筛选`:'已清除标签筛选')})});
renderVerticalList();
